sys_script_include.script:
var EventUtilsClient = Class.create();
EventUtilsClient.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {


    // Fetch event details by sys_id
    getEventDetails: function() {
        var eventId = this.getParameter('sysparm_event_id');
        var gr = new GlideRecord('Event_Record');
        if (gr.get(eventId)) {
            var result = {
                name: gr.getValue('u_event_name'),
                date: gr.getDisplayValue('u_event_date'),
                location: gr.getValue('u_location')
            };
            return JSON.stringify(result);
        }
        return JSON.stringify({});
    },

    // Check if event is VIP
    isVIP: function() {
        var eventId = this.getParameter('sysparm_event_id');
        var gr = new GlideRecord('Event_Record');
        if (gr.get(eventId)) {
            return gr.getValue('u_vip') == 'true' ? 'true' : 'false';
        }
        return 'false';
    }
});

    type: 'EventUtilsClient'
